tmpls.afmt:
{{FrontSide}}

<hr id=answer>

<!-- Displays the chosen algorithm in a big font.
		The chosen algorithm can change dependant on what
		is in the "Select Case to Use" field. 
		If the number "1" is in that field, "Alternative Case 1"
		will be used. If the number is "2", "Alternative Case 2"
		will be used and so on. If the value is not between
		1 and 4, the default algorithm will be used. 

		By default I set this field to "0" because 
		I want to use the default algorithm. However 
		this is not necessary. -->

<span style="font-size:150%;" id="correct_answer" >{{Algorithm}}</span>
<br/>
<br/>

<!-- This code displays the name/number of the algorithm if it has one. 
 		If it does not have a name, the text "Algorithm name" is not displayed.-->

{{#Case Name}}Algorithm name: {{/Case Name}}<span style="font-weight:bold;">{{Case Name}}</span>
{{#Case Name}}<br/>{{/Case Name}}

<!-- The probability is displayed if it is given. 
		Note: certain probabilities can be given colours by filling
		in the "Probability Colours" Field, for example like this:

		1/18:blue;1/36:green;1/72:red;

		This would make the probability "1/18" blue, "1/36" red and so on.
		Make sure there are no spaces what so ever or no new lines. 
		If you do not want to keep filling in this field every time you make
 		a card, use the "Frozen Fields" addon by Glutanimate.-->

<span id="prob">{{Probability}}</span>
{{#Probability}}
<br/><br/>
{{/Probability}}


<!-- These fields are only displayed so that the 
        the javascript code can access them. The actual results
        is displayed in the "final_alts" span tag.--> 

<span id="alternative1">{{Alternative Case 1}}</span>
<span id="alternative2">{{Alternative Case 2}}</span>
<span id="alternative3">{{Alternative Case 3}}</span>
<span id="alternative4">{{Alternative Case 4}}</span>
<span id="condition">{{Select Case to Use}}</span>
<span id="prob_colours">{{Probability Colours}}</span>

<!-- This is where the alternative cases will show -->

<span id="final_alts"></span>


<!-- The following is some code written in "javascript" -->
<!-- PLEASE DO NOT EDIT THIS SCRIPT IF YOU DO NOT KNOW
		WHAT YOU ARE DOING.-->

<script type="text/javascript">

  prob_colours = document.getElementById("prob_colours");

  prob = document.getElementById('prob');
  is_prob = prob.innerHTML != "";

  prob_colours_split = prob_colours.innerHTML.split(";");

  for (i = 0; i < prob_colours_split.length; i++) {
    prob_colours_split[i] = prob_colours_split[i].split(":");

    if (prob.innerHTML == prob_colours_split[i][0]) {
      prob.style.color = prob_colours_split[i][1];
    }
  }

  if (is_prob) {
  prob.innerHTML = "Probability: {{Probability}}";
  }

  // Getting the "Select case to use" field.
  var conditional = document.getElementById("condition");


  // Getting "Alternative cases" field
  // Gets the actual field, as well as getting whether the 
  // field contains text or not.
  // The variables that indicate if the field contains text
  // end in "_bool"

  var alternative1 = document.getElementById("alternative1");
  var alternative1_bool = document.getElementById("alternative1").innerHTML != "";

  var alternative2 = document.getElementById("alternative2");
  var alternative2_bool = document.getElementById("alternative2").innerHTML != "";

  var alternative3 = document.getElementById("alternative3");
  var alternative3_bool = document.getElementById("alternative3").innerHTML != "";

  var alternative4 = document.getElementById("alternative4");
  var alternative4_bool = document.getElementById("alternative4").innerHTML != "";


  // "Final_alts" is how the alternative algorithms will finally look like 
  // on the backside of the card, after all the formatting is done.

  var final_alts = document.getElementById("final_alts");

  // Getting the "Recommended algorithm" field.

  var recommended_alg = document.getElementById("correct_answer");

  // This IF statement checks if any of the "alternative case" fields
  // contains any text, it will then go on the execute another
  // IF statement which checks the "Select Case to Use"
  // statement to see whether one of those alternative
  // cases should actually be used.

  if (alternative1_bool || alternative2_bool || alternative3_bool || alternative4_bool) {
    execute_conditional = true;
  } 

  // Otherwise, if none of the "alternative case" fields contain any text,
  // then "No alternative cases." is displayed.

  else {
    final_alts.innerHTML = "No alternative cases."
    execute_conditional = false;
  }


  // This IF statement runs through all the options for
  // the field "Select Case to Use". The possible options
  // are 1,2,3 and 4. If it is one of these options,
  // then that Alternative Case will be checked (to 
  // see if it contains any text), and if it does, then
  // That will be the main algorithm that is displayed.
  // If the "Select case to Use" field is not 1,2,3 or 4,
  // then the main algorithm will be shown and all
  // the others will be shown under "Alternative Cases".
  // By default the "Select case to Use" field contains the
  // value "0".

  if (execute_conditional == true) {

    if (conditional.innerHTML == "1" && alternative1_bool) {

      recommended_alg.innerHTML = "{{Alternative Case 1}}";
      if (alternative2_bool || alternative3_bool || alternative4_bool) {
        final_alts.innerHTML = "Recommended Case: {{Algorithm}}<br><br>Alternative Cases:<br>{{Alternative Case 2}}<br>{{Alternative Case 3}}<br>{{Alternative Case 4}}";
	  } else {
        final_alts.innerHTML = "Recommended Case: {{Algorithm}}";
      }


    } else if (conditional.innerHTML == "2" && alternative2_bool) {

      recommended_alg.innerHTML = "{{Alternative Case 2}}";
      final_alts.innerHTML = "Recommended Case: {{Algorithm}}<br><br>Alternative Cases:<br>{{Alternative Case 1}}<br>{{Alternative Case 3}}<br>{{Alternative Case 4}}";


    } else if (conditional.innerHTML == "3" && alternative3_bool) {

      recommended_alg.innerHTML = "{{Alternative Case 3}}";
      final_alts.innerHTML = "Recommended Case: {{Algorithm}}<br><br>Alternative Cases:<br>{{Alternative Case 1}}<br>{{Alternative Case 2}}<br>{{Alternative Case 4}}"


    } else if (conditional.innerHTML == "4" && alternative4_bool) {

      recommended_alg.innerHTML = "{{Alternative Case 4}}";
      final_alts.innerHTML = "Recommended Case: {{Algorithm}}<br><br>Alternative Cases:<br>{{Alternative Case 1}}<br>{{Alternative Case 2}}<br>{{Alternative Case 3}}"


    } else {
      final_alts.innerHTML = "Alternative Cases:<br>{{Alternative Case 1}}<br>{{Alternative Case 2}}<br>{{Alternative Case 3}}<br>{{Alternative Case 4}}"
    }      
  }

  // Setting all the unnecessary fields to nothing.

  conditional.innerHTML = "";
  alternative1.innerHTML = "";
  alternative2.innerHTML = "";
  alternative3.innerHTML = "";
  alternative4.innerHTML = "";
  prob_colours.innerHTML = "";

</script>

